css:
.rail{display:flex; gap:22px; overflow-x:auto; scroll-snap-type:x mandatory;
  margin-inline:calc(50% - 50vw); padding-inline:48px}
.rail>li{flex:0 0 300px; scroll-snap-align:center}
.rail::-webkit-scrollbar{display:none}
/* 右だけ切る（左は版面に揃える） */
.rail--r{margin-left:0; margin-right:calc(50% - 50vw); padding-right:30vw}
/* 文字が途中で切れるのを許す */
.rail li p{white-space:nowrap; overflow:hidden}
/* 隙間ゼロの帯にする場合 */
.strip{display:flex; gap:0; width:100vw; margin-left:calc(50% - 50vw); height:160px}
.strip img{flex:1 1 0; min-width:0; height:100%; object-fit:cover}
